begin;
do $review$
declare p public.hb_policy_versions%rowtype; reviewed timestamptz:=now(); next_version integer;
begin
 select * into strict p from public.hb_policy_versions where policy_key='service:umm-al-quwain-trade-name-official-path' and status='active' for update;
 if p.reviewed_by='uaq-local-booking-card-2026-10-18' then return; end if;
 if p.version<>1 or jsonb_array_length(p.rules)<>4 or not exists(select 1 from jsonb_array_elements(p.rules) r where r->>'id'='requirement:1' and r->>'reason'='اختيار اسم متوافق مع النشاط والشكل القانوني') then raise exception 'UAQ active policy changed; review before applying'; end if;
 select coalesce(max(version),0)+1 into next_version from public.hb_policy_versions where policy_key=p.policy_key and jurisdiction_id is not distinct from p.jurisdiction_id;
 update public.hb_policy_versions set status='retired',effective_until=reviewed where id=p.id;
 insert into public.hb_policy_versions(policy_key,jurisdiction_id,version,effective_from,status,rules,source_ids,reviewed_by,reviewed_at,country_pack_id) values(p.policy_key,p.jurisdiction_id,next_version,reviewed,'active',$rules$[{"id":"requirement:1","when":[],"effect":"review","reason":"للمواطن أو مواطن مجلس التعاون: أصل الهوية وصورة جواز السفر والبريد الإلكتروني ورقم الهاتف لصاحب الرخصة.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:2","when":[],"effect":"review","reason":"للمدير المسؤول الوافد: أصل الهوية وصورة جواز السفر والإقامة والبريد الإلكتروني ورقم الهاتف.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:3","when":[],"effect":"review","reason":"خطاب عدم ممانعة مصدق من الكفيل أو صورة رخصة المستثمر بحسب الحالات المحددة في البطاقة، مع متطلبات إضافية لمدير الفرع عند اختلافه.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:4","when":[],"effect":"review","reason":"ثلاثة أسماء تجارية مكتوبة تدل على النشاط بالعربية ومترجمة إلى الإنجليزية.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:5","when":[],"effect":"review","reason":"وكالة عند غياب صاحب العلاقة.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:6","when":[],"effect":"review","reason":"طباعة الأنشطة المطلوبة والبريد الإلكتروني ورقم الهاتف المتعلقين بالرخصة.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"requirement:7","when":[],"effect":"review","reason":"تحديد ما إذا كانت الرخصة تتبع برنامج الشيخ سعود لمشاريع الشباب.","actions":["collect_or_verify_requirement"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]},{"id":"conditions","when":[],"effect":"review","reason":"تختلف المستندات بحسب الجنسية وصفة المدير والفرع والتمثيل بوكالة؛ راجع الحالات المحددة في بطاقة الدائرة. حجز الاسم التجاري لا يمثل إصدار الرخصة. تذكر خانة الرسوم «حسب الطلب» دون مبلغ، ولا تُنشر مدة إنجاز محددة؛ أكد المبلغ والمدة مع الدائرة.","actions":["review_conditions"],"sourceRefs":["https://ded.uaq.ae/en/our-activities/service/bookingtradename.html"]}]$rules$::jsonb,p.source_ids,'uaq-local-booking-card-2026-10-18',reviewed,p.country_pack_id);
 update public.hb_policy_sources set source_url='https://ded.uaq.ae/en/our-activities/service/bookingtradename.html',last_verified_at=reviewed,review_required=false,metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('review_checkpoint','uaq-local-booking-card-2026-10-18','reverified_at',reviewed,'verification_scope','documents_conditional_requirements_official_destination','verification_state','OFFICIAL_LINK_AND_DETAILS_VERIFIED','unpublished_facts',jsonb_build_array('fee_amount','duration'),'previous_directory_source',source_url) where id='ae316cb4-f600-4d56-9fee-fc990d5615c0' and id=any(p.source_ids) and active and source_url='https://u.ae/en/information-and-services/business/important-digital-services/inquire-about-licences-names-and-activities';
 if not found then raise exception 'Expected UAQ source absent';end if;
end $review$;
commit;
